<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login SIMRS</title><style>body{font-family:Arial;background:#eef5ff;display:flex;min-height:100vh;align-items:center;justify-content:center}.box{width:360px;background:white;border-radius:16px;padding:26px;box-shadow:0 10px 30px rgba(0,0,0,.08)}input{width:100%;box-sizing:border-box;padding:11px;border:1px solid #cbd5e1;border-radius:8px;margin:7px 0 14px}.btn{width:100%;border:0;background:#12355b;color:white;padding:12px;border-radius:8px}.err{background:#fee2e2;padding:10px;border-radius:8px;margin-bottom:10px}</style></head><body><div class="box"><h2>Login SIMRS</h2><?php if(!empty($error)): ?><div class="err"><?= esc($error) ?></div><?php endif; ?><form method="post"><label>Username</label><input name="username" required><label>Password</label><input type="password" name="password" required><button class="btn">Masuk</button></form><p style="font-size:12px;color:#64748b">Gunakan user dari tabel <code>mlite_users</code>. Bila belum ada, insert user admin sesuai README.</p></div></body></html>